tool_calls.arguments:
{"command":"kubectl patch deployment app -n default --type merge --patch '
{
  "spec": {
    "template": {
      "spec": {
        "volumes": [
          {
            "name": "nginx-cache",
            "emptyDir": {}
          }
        ],
        "containers": [
          {
            "name": "app",
            "volumeMounts": [
              {
                "name": "nginx-cache",
                "mountPath": "/var/cache/nginx"
              }
            ]
          }
        ]
      }
    }
  }
}'"}

{"command":"kubectl patch deployment app -n default --type json -p '[
  {"op": "add", "path": "/spec/template/spec/volumes", "value": [{"name": "nginx-cache", "emptyDir": {}}]},
  {"op": "add", "path": "/spec/template/spec/containers/0/volumeMounts", "value": [{"name": "nginx-cache", "mountPath": "/var/cache/nginx"}]}
]'"}

{"command":"kubectl patch deployment app -n default --type json -p '[
  {"op": "add", "path": "/spec/template/spec/volumes", "value": [{"name": "nginx-run", "emptyDir": {}}]},
  {"op": "add", "path": "/spec/template/spec/containers/0/volumeMounts", "value": [{"name": "nginx-run", "mountPath": "/run"}]}
]'"}

{"command":"kubectl create configmap nginx-temp-config --from-file nginx.conf.template='
http {
    # Define the temporary directory for client requests
    client_temp_path /var/cache/nginx/temp;
    # Define the temporary directory for body data
    client_body_temp_path /var/cache/nginx/temp;
}
' -n default
kubectl get cm nginx-temp-config -n default"}

{"command":"cat <<EOF | kubectl apply -f -
apiVersion: v1
kind: ConfigMap
metadata:
  name: nginx-temp-config
  namespace: default
data:
  nginx.conf: |
    http {
        client_temp_path /var/cache/nginx/temp;
        client_body_temp_path /var/cache/nginx/temp;
    }
EOF
kubectl get cm nginx-temp-config -n default"}

{"command":"kubectl patch deployment app -n default --type json -p '[
  {"op": "add", "path": "/spec/template/spec/volumes", "value": [{"name": "nginx-config", "configMap": {"name": "nginx-temp-config"}}]},
  {"op": "add", "path": "/spec/template/spec/containers/0/volumeMounts", "value": [{"name": "nginx-config", "mountPath": "/etc/nginx/nginx.conf", "subPath": ""}]},
  {"op": "replace", "path": "/spec/template/spec/containers/0/command", "value": ["nginx", "-c", "/etc/nginx/nginx.conf"]}
]'"}

